/** Search panel: lazy index from the hidden CMS list, client-side matching, textContent rendering. */
import { on } from "../utils/events.js";
import { qs, qsa } from "../utils/dom.js";
import * as overlay from "../utils/overlay.js";

const norm = (s) => (s || "").toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");

export default function init(root, opts = {}) {
  const input = qs("input[type='search'], input[type='text']", root);
  const out = qs("[data-mhs-results]", root);
  const status = qs("[data-mhs-status]", root);
  const max = Number(opts.max) || 8;
  const emptyText = opts.emptyText || "No result for";
  let index = null;
  const buildIndex = () => index || (index = qsa('[data-mhs="search-index"] a').map((a) => ({ name: a.textContent.trim(), meta: a.dataset.mhsMeta || a.dataset.meta || "", href: a.getAttribute("href") || "#" })).filter((i) => i.name));

  function render(q) {
    out.replaceChildren();
    if (!q) { if (status) status.textContent = ""; return; }
    const nq = norm(q);
    const hits = buildIndex().filter((i) => norm(i.name).includes(nq) || norm(i.meta).includes(nq)).slice(0, max);
    if (!hits.length) { const p = document.createElement("p"); p.className = "c-search__empty"; p.textContent = `${emptyText} "${q}".`; out.appendChild(p); }
    for (const hit of hits) {
      const a = document.createElement("a"); a.className = "c-search__item"; a.href = hit.href;
      const n = document.createElement("span"); n.className = "c-search__name"; n.textContent = hit.name;
      const m = document.createElement("span"); m.className = "c-search__meta"; m.textContent = hit.meta;
      a.append(n, m); out.appendChild(a);
    }
    if (status) status.textContent = hits.length ? `${hits.length} result${hits.length > 1 ? "s" : ""}` : "No results";
  }
  const show = (trigger) => overlay.open(root, { trigger, lockScroll: false, onClose: () => { input.value = ""; render(""); } });
  qsa('[data-mhs="search-open"]').forEach((btn) => btn.addEventListener("click", (e) => { e.preventDefault(); overlay.isOpen(root) ? overlay.close(root) : show(btn); }));
  on(root, "click", "[data-mhs-close]", () => overlay.close(root));
  if (input && out) input.addEventListener("input", () => render(input.value.trim()));
  return { destroy() {} };
}
