/** Quote selection persisted in localStorage under "mhs-quote" (same schema as today). */
import { emit } from "../utils/events.js";
const KEY = "mhs-quote";
const same = (a, b) => a.slug === b.slug && (a.size || "") === (b.size || "");
function read() { try { return JSON.parse(localStorage.getItem(KEY)) || []; } catch (_) { return []; } }
function write(items) { try { localStorage.setItem(KEY, JSON.stringify(items)); } catch (_) { /* private mode */ } emit("mhs:quote:change", { items, count: count(items) }); }
export function items() { return read(); }
export function count(list = read()) { return list.reduce((n, i) => n + (Number(i.qty) || 0), 0); }
export function add(product, qty = 1) {
  const list = read(); const hit = list.find((i) => same(i, product));
  if (hit) hit.qty = (Number(hit.qty) || 0) + qty;
  else list.push({ name: product.name || "Rug", collection: product.collection || "", variant: product.variant || "", size: product.size || "", slug: product.slug || "", image: product.image || "", qty });
  write(list);
}
export function update(slug, size, delta) {
  const list = read(); const hit = list.find((i) => same(i, { slug, size }));
  if (!hit) return; hit.qty = Math.max(1, (Number(hit.qty) || 1) + delta); write(list);
}
export function remove(slug, size) { write(read().filter((i) => !same(i, { slug, size }))); }
export function clear() { write([]); }
export function summary(list = read()) {
  return list.map((i, n) => {
    let line = `${n + 1}. ${i.name}`;
    if (i.collection) line += ` — ${i.collection}`;
    if (i.variant) line += ` / ${i.variant}`;
    if (i.size) line += ` | Size: ${i.size}`;
    return line + ` | Qty: ${i.qty}`;
  }).join("\n");
}
