/** Webflow forms: detect the runtime's success/failure blocks and announce them; emit mhs:form:success. */
import { emit } from "../utils/events.js";
import { qs } from "../utils/dom.js";

export default function init(root) {
  const form = root.tagName === "FORM" ? root : qs("form", root);
  const wrap = form ? form.parentElement : root;
  const done = qs(".w-form-done, .c-form__done", wrap);
  const fail = qs(".w-form-fail, .c-form__fail", wrap);
  if (done) done.setAttribute("role", "status");
  if (fail) fail.setAttribute("role", "alert");
  let fired = false; let mo;
  if (done && "MutationObserver" in window) {
    mo = new MutationObserver(() => {
      const visible = done.style.display !== "none" && getComputedStyle(done).display !== "none";
      if (visible && !fired) { fired = true; emit("mhs:form:success", { form }); }
      if (!visible) fired = false;
    });
    mo.observe(done, { attributes: true, attributeFilter: ["style", "class"] });
  }
  return { destroy() { mo && mo.disconnect(); } };
}
