/**
 * Overlay manager: one Escape listener, reference-counted scroll lock, focus return, focus trap for dialogs.
 * Uses the native popover API when the element carries a `popover` attribute, class toggling otherwise.
 */
import { FOCUSABLE, qsa } from "./dom.js";
import { supportsPopover } from "./motion.js";

const stack = [];      // [{ el, trigger, onClose }]
let lockCount = 0;
const LOCK_CLASS = "is-scroll-locked";

function lock() { if (lockCount++ === 0) document.documentElement.classList.add(LOCK_CLASS); }
function unlock() { if (--lockCount <= 0) { lockCount = 0; document.documentElement.classList.remove(LOCK_CLASS); } }
const usesPopover = (el) => el.hasAttribute("popover") && supportsPopover();

function setState(el, open) {
  if (usesPopover(el)) { try { open ? el.showPopover() : el.hidePopover(); } catch (_) { /* already in that state */ } }
  el.classList.toggle("is-open", open);
  if (el.hasAttribute("popover") && !supportsPopover()) el.hidden = !open;
}

export function isOpen(el) { return usesPopover(el) ? el.matches(":popover-open") : el.classList.contains("is-open"); }

export function open(el, { trigger = document.activeElement, onClose, lockScroll = true, focus = true } = {}) {
  if (!el || isOpen(el)) return;
  setState(el, true);
  stack.push({ el, trigger, onClose, lockScroll });
  if (lockScroll) lock();
  if (trigger && trigger.setAttribute) trigger.setAttribute("aria-expanded", "true");
  if (focus) {
    const target = el.querySelector("[data-mhs-focus]") || el.querySelector(FOCUSABLE) || el;
    const tryFocus = () => { target.focus({ preventScroll: true }); if (document.activeElement !== target) setTimeout(() => target.focus({ preventScroll: true }), 60); };
    requestAnimationFrame(tryFocus);
  }
}

export function close(el) {
  const i = stack.findIndex((s) => s.el === el);
  if (i === -1) return;
  const [entry] = stack.splice(i, 1);
  setState(el, false);
  if (entry.lockScroll) unlock();
  if (entry.trigger && entry.trigger.setAttribute) entry.trigger.setAttribute("aria-expanded", "false");
  if (entry.trigger && entry.trigger.focus) entry.trigger.focus({ preventScroll: true });
  if (entry.onClose) entry.onClose();
}

export function toggle(el, opts) { isOpen(el) ? close(el) : open(el, opts); }
export function closeAll() { while (stack.length) close(stack[stack.length - 1].el); }

let bound = false;
export function bindGlobal() {
  if (bound) return; bound = true;
  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape" && stack.length) { e.preventDefault(); close(stack[stack.length - 1].el); return; }
    if (e.key === "Tab" && stack.length) {
      const top = stack[stack.length - 1].el;
      if (top.getAttribute("role") !== "dialog") return;
      const items = qsa(FOCUSABLE, top).filter((n) => n.offsetParent !== null || n === document.activeElement);
      if (!items.length) return;
      const first = items[0], last = items[items.length - 1];
      if (e.shiftKey && document.activeElement === first) { e.preventDefault(); last.focus(); }
      else if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first.focus(); }
    }
  });
  // native popovers can be light-dismissed by the platform: keep the stack in sync
  document.addEventListener("toggle", (e) => {
    const el = e.target;
    if (el && el.hasAttribute && el.hasAttribute("popover") && e.newState === "closed" && stack.some((s) => s.el === el)) close(el);
  }, true);
}
