/** Navigation: solid state after the sentinel scrolls out; mobile panel open/close. */
import { on } from "../utils/events.js";
import { qs } from "../utils/dom.js";
import * as overlay from "../utils/overlay.js";

export default function init(root, opts = {}) {
  const threshold = Number(opts.threshold) || 60;
  const alwaysSolid = document.documentElement.dataset.theme === "light" || document.body.dataset.theme === "light" || opts.solid === true;
  let observer;
  if (alwaysSolid) root.classList.add("is-solid");
  else {
    // the sentinel must live in the document flow (not inside the fixed header) so that it scrolls out of view
    let sentinel = qs(".c-nav__sentinel", root) || qs("body > .c-nav__sentinel");
    if (!sentinel) { sentinel = document.createElement("span"); sentinel.className = "c-nav__sentinel"; }
    if (sentinel.parentElement !== document.body) document.body.prepend(sentinel);
    sentinel.setAttribute("aria-hidden", "true"); sentinel.style.top = `${threshold}px`;
    if ("IntersectionObserver" in window) {
      observer = new IntersectionObserver(([entry]) => root.classList.toggle("is-solid", !entry.isIntersecting && entry.boundingClientRect.top < 0), { threshold: 0 });
      observer.observe(sentinel);
    } else {
      const tick = () => root.classList.toggle("is-solid", window.scrollY > threshold);
      window.addEventListener("scroll", tick, { passive: true }); tick();
    }
  }
  const panel = qs('[data-mhs="nav-mobile"]', root) || qs('[data-mhs="nav-mobile"]');
  if (panel) {
    on(root, "click", '[data-mhs="nav-open"]', (e, btn) => { e.preventDefault(); overlay.open(panel, { trigger: btn }); });
    on(panel, "click", '[data-mhs="nav-close"], a[href]', () => overlay.close(panel));
  }
  return { destroy() { observer && observer.disconnect(); } };
}
