/**
 * mhs.js — boot + registry. Global modules are static imports (needed on every shell page);
 * page modules are dynamic imports (esbuild code-splits them into chunks loaded only when their root exists).
 */
import { readOptions } from "./utils/dom.js";
import * as overlay from "./utils/overlay.js";
import navigation from "./modules/navigation.js";
import search from "./modules/search.js";
import drawer from "./modules/drawer.js";
import forms from "./modules/forms.js";

const registry = {
  nav: () => navigation,
  search: () => search,
  drawer: () => drawer,
  form: () => forms,
  // page modules: lazy chunks, loaded only when their root exists on the page
  filters: () => import("./modules/filters.js").then((m) => m.default),
  pdp: () => import("./modules/product.js").then((m) => m.default),
};

const instances = new WeakMap();

export async function mount(root) {
  if (instances.has(root)) return instances.get(root);
  const name = root.dataset.mhs;
  const loader = registry[name];
  if (!loader) return null;
  try {
    const init = await loader();
    const instance = init(root, readOptions(root)) || {};
    instances.set(root, instance);
    root.dataset.mhsReady = "true";
    return instance;
  } catch (err) {
    console.error(`[mhs] ${name} failed to mount`, err);
    return null;
  }
}

export function scan(scope = document) {
  scope.querySelectorAll("[data-mhs]").forEach((root) => { if (registry[root.dataset.mhs]) mount(root); });
}

function boot() {
  if (window.__MHS__) return;            // second copy of the bundle → no-op
  window.__MHS__ = { version: __MHS_VERSION__, mount, scan };
  overlay.bindGlobal();
  scan();
  window.addEventListener("pageshow", (e) => { if (e.persisted) document.dispatchEvent(new CustomEvent("mhs:quote:change", { detail: {} })); });
}

document.readyState === "loading" ? document.addEventListener("DOMContentLoaded", boot) : boot();
