/** Quote drawer: renders the store, quantity/remove, syncs the hidden form field, badge, open/close. */
import * as store from "./quote-store.js";
import { on, listen } from "../utils/events.js";
import { qs, qsa, fromTemplate } from "../utils/dom.js";
import * as overlay from "../utils/overlay.js";

export default function init(root, opts = {}) {
  const itemsEl = qs("[data-mhs-items]", root);
  const emptyEl = qs("[data-mhs-empty]", root);
  const field = qs('[name="quote-items"]', root);
  const tpl = qs("template[data-mhs-item]", root) || document.getElementById(opts.template || "mhs-quote-item");
  const badges = qsa('[data-mhs="quote-badge"]');
  const triggers = qsa('[data-mhs="quote-trigger"]');
  const scrim = qs('[data-mhs="scrim"]');

  function badge() {
    const n = store.count();
    badges.forEach((b) => { b.textContent = String(n); b.classList.toggle("is-visible", n > 0); });
  }
  function render() {
    const list = store.items();
    if (itemsEl) {
      itemsEl.replaceChildren();
      for (const item of list) {
        const node = tpl ? fromTemplate(tpl) : null;
        if (!node) break;
        node.dataset.slug = item.slug; node.dataset.size = item.size || "";
        const img = qs("[data-mhs-thumb]", node);
        if (img) { if (item.image) { img.src = item.image; img.alt = item.name; } else { img.remove(); } }
        const set = (sel, text) => { const el = qs(sel, node); if (el) el.textContent = text; };
        set("[data-mhs-name]", item.name);
        set("[data-mhs-meta]", [item.collection, item.variant].filter(Boolean).join(" — "));
        const sizeEl = qs("[data-mhs-size]", node); if (sizeEl) { item.size ? (sizeEl.textContent = `Size: ${item.size}`) : sizeEl.remove(); }
        set("[data-mhs-qty]", String(item.qty));
        itemsEl.appendChild(node);
      }
    }
    if (emptyEl) emptyEl.hidden = list.length > 0;
    if (field) field.value = store.summary(list);
    badge();
  }
  const show = (trigger) => { render(); if (scrim) scrim.classList.add("is-open"); overlay.open(root, { trigger, onClose: () => scrim && scrim.classList.remove("is-open") }); };

  triggers.forEach((t) => t.addEventListener("click", (e) => { e.preventDefault(); show(t); }));
  on(root, "click", "[data-mhs-close]", () => overlay.close(root));
  if (scrim) scrim.addEventListener("click", () => overlay.close(root));
  on(root, "click", "[data-mhs-plus]", (_, b) => { const li = b.closest("[data-slug]"); store.update(li.dataset.slug, li.dataset.size, 1); });
  on(root, "click", "[data-mhs-minus]", (_, b) => { const li = b.closest("[data-slug]"); store.update(li.dataset.slug, li.dataset.size, -1); });
  on(root, "click", "[data-mhs-remove]", (_, b) => { const li = b.closest("[data-slug]"); store.remove(li.dataset.slug, li.dataset.size); });

  const offs = [
    listen("mhs:quote:change", render),
    listen("mhs:quote:add", (e) => { store.add(e.detail.product, e.detail.qty || 1); show(e.detail.trigger); }),
    listen("mhs:form:success", (e) => { if (root.contains(e.detail.form)) store.clear(); }),
  ];
  render();
  return { destroy() { offs.forEach((f) => f()); } };
}
